import java.io.*;
import android.widget.*;
import com.mcal.bshengine.*;

final BshEngineActivity activity = ZActivity;

final File projectDir = ZScopedStorage.getProject();
final File smaliDir = ZScopedStorage.getSmali();
final File resDir = ZScopedStorage.getRes();
final File manifest = ZScopedStorage.getManifest();

final TextView textLog = activity.findViewById(R.id.main_text);

final String PATTERN = "<application(.+)android:name=\"([^\"]+)\"(.+)";

public void patchSmali() {
	final String hook = "";
	final File path = new File(smaliDir.getPath() + "/cc/binmt/signature");
	final File hookPath = new File(path.getPath() + "/PmsHookApplication.smali");

	final String replaceSignature = ZCipher.decodeBase64(hook).replace("### Signatures Data ###", ZSignature.getSignature());

	// TODO replace application name

	if(!path.exists()) {
		path.mkdirs();
	}
	hookPath.createNewFile();

	ZFileHelper.writeToFile(hookPath.getPath(), replaceSignature);
	ZLogger.info(textLog, "Dex patched");
}

public void patchManifest() {
	final String manifestText = ZFileHelper.readFile(manifest.getPath());
	final String matchedText = ZMatcher.replaceGroup(PATTERN, manifestText, 2, "cc.binmt.signature.PmsHookApplication");
	ZFileHelper.writeToFile(manifest.getPath(), matchedText);
	ZLogger.info(textLog, "Manifest patched");
}


public void onCreate() {
	patchManifest();
	patchSmali();
	ZLogger.info(textLog, "Patching finished");
	ZToast.show("Done", true);
}

onCreate();
